\section{Introduction}

Let $N = pq$ be a product of two distinct primes. A recurring question in the analysis of
factoring is whether some elementary, publicly computable statistic of $N$ encodes the hidden
pair $(p,q)$. Many do; the interest lies not in whether a statistic is informative but in the
interaction between what it encodes and what it costs.

This paper carries out that analysis in full for the family of \emph{gcd moments}
\[
  M_k(N) \;=\; \sum_{x=0}^{N-1}\gcd(N,x)^k, \qquad k \ge 1 .
\]
The case $k=1$ is the classical gcd-sum function. The higher moments are the natural
re-weightings that emphasise the rare large gcd values against the overwhelming majority of
coprime residues.

Our results show that the family is \emph{closed} in a strong sense: every moment is an explicit
polynomial in the modulus $N$ and the trace $s = p+q$; the first moment already determines $s$;
and every higher moment is therefore an explicit function of $N$ and $M_1$. No moment carries
more than the trace, and the trace is exactly enough to factor. The hierarchy indexed by $k$ is
not an information hierarchy but a \emph{cost} hierarchy, and it runs in the wrong direction,
with sampling variance of order $N^{2k-1}$.

We then analyse the structure behind this: $M_k$ is multiplicative, indeed an Euler product on
squarefree moduli, and the whole discussion can be recast as the study of a strictly monotone
function on the lattice of factorisations of $n$ ordered by refinement. This yields sharp
inversion theorems: a complete classification of second-moment collisions, unconditional
identifiability at every $k \ge 3$, and separation results controlled by $\bigOmega(n)$.

\subsection*{Conventions}
$\varphi$ is Euler's totient; $\bigOmega(n)$ counts prime factors with multiplicity;
$p^e \,\|\, n$ means $p^e \mid n$ and $p^{e+1} \nmid n$; a \emph{factorisation} of $n$ is a finite
multiset of integers $\ge 2$ with product $n$; a \emph{semiprime} always means a product of two
\emph{distinct} primes. Sums over $x$ run over $0 \le x < n$, so the term $x=0$ contributes
$\gcd(n,0)^k = n^k$.

\section{The divisor form and multiplicativity}

\begin{definition}
For $k, n \ge 1$ put $M_k(n) = \sum_{x=0}^{n-1}\gcd(n,x)^k$.
\end{definition}

\begin{theorem}[Divisor form]\label{thm:divisor}
For every $n \ge 1$ and $k \ge 0$,
\[
  M_k(n) \;=\; \sum_{d \mid n} d^k\,\varphi(n/d).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition the residues $x < n$ by the value $d = \gcd(n,x)$, necessarily a divisor of $n$. The
fibre over $d$ consists of $x = dy$ with $y < n/d$ and $\gcd(n/d,y)=1$, hence has $\varphi(n/d)$
elements, each contributing $d^k$.
\end{proof}

Thus $M_k = \Id_k * \varphi$ is a Dirichlet convolution of multiplicative functions.

\begin{corollary}
If $\gcd(m,n)=1$ and $m,n \ge 1$ then $M_k(mn) = M_k(m)M_k(n)$.
\end{corollary}

\begin{proposition}[Local factors]\label{prop:local}
For $p$ prime and $e \ge 1$,
\[
  M_k(p) = p^k + p - 1, \qquad
  M_k(p^e) = \sum_{i=0}^{e} p^{ik}\varphi(p^{e-i}) = p^{ek} + (p-1)\sum_{i=0}^{e-1}p^{ik}p^{\,e-1-i},
\]
and $M_k(p^{e+1}) = p^k M_k(p^e) + \varphi(p^{e+1})$.
\end{proposition}

\begin{corollary}[Euler product on squarefree moduli]\label{cor:euler}
If $n$ is squarefree then $M_k(n) = \prod_{p \mid n}\big(p^k+p-1\big)$.
\end{corollary}

On squarefree moduli the moment is \emph{completely split}, one local factor per prime.
Everything below analyses how those local factors combine.

\section{The semiprime closed form}

Fix distinct primes $p,q$, put $N = pq$ and $s = p+q$.

\begin{definition}
Define $P_0 = 2$, $P_1 = s$ and $P_{j+2} = sP_{j+1} - NP_j$.
\end{definition}

\begin{lemma}\label{lem:newton}
$P_j = p^j + q^j$ for all $j \ge 0$.
\end{lemma}

\begin{proof}[Proof sketch]
Both sides satisfy the same two-term linear recursion, since $p,q$ are the roots of
$t^2 - st + N$; the two initial values agree.
\end{proof}

\begin{theorem}[Four-term expansion]\label{thm:fourterm}
For all $k \ge 0$,
\[
  M_k(pq) \;=\; (p-1)(q-1) + p^k(q-1) + q^k(p-1) + (pq)^k .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The divisors of $pq$ are $1,p,q,pq$; apply Theorem~\ref{thm:divisor} with
$\varphi(pq) = (p-1)(q-1)$.
\end{proof}

\begin{theorem}[Closed form; the symmetry barrier]\label{thm:closed}
For every $k \ge 1$,
\[
  M_k(N) \;=\; N^k + N P_{k-1} - P_k + N - s + 1 \;=:\; F_k(N,s).
\]
\end{theorem}

\begin{proof}[Proof sketch]
In Theorem~\ref{thm:fourterm}, $p^k(q-1)+q^k(p-1) = pq(p^{k-1}+q^{k-1}) - (p^k+q^k)
= NP_{k-1} - P_k$, while $(p-1)(q-1) = N-s+1$ and $(pq)^k = N^k$.
\end{proof}

\begin{corollary}[Explicit low moments]
\[
\begin{aligned}
M_1 &= 4N - 2s + 1, \\
M_2 &= N^2 + 3N + 1 + (N-1)s - s^2, \\
M_3 &= N^3 - 2N^2 + Ns^2 + 3Ns + N - s^3 - s + 1, \\
M_4 &= N^4 - 3N^2s - 2N^2 + Ns^3 + 4Ns^2 + N - s^4 - s + 1 .
\end{aligned}
\]
\end{corollary}

\begin{example}
At $N=6$ ($p=2,q=3,s=5$): $M_1 = 15$ and $M_2 = 55$, matching a direct scan. At $N=15$ ($s=8$):
$M_1 = 45$.
\end{example}

Theorem~\ref{thm:closed} is the \emph{symmetry barrier}: the hidden primes enter every moment only
through the elementary symmetric functions $N = pq$ and $s = p+q$.

\begin{corollary}[Trace recovery]\label{cor:trace}
$2s = 4N + 1 - M_1(N)$.
\end{corollary}

\begin{theorem}[Closure of the family]\label{thm:closure}
Let $s$ be defined by $2s = 4N+1-M_1(N)$. Then $M_k(N) = F_k(N,s)$ for every $k \ge 1$. Hence
every gcd moment is an explicit polynomial function of the modulus and the \emph{first} moment.
\end{theorem}

\begin{theorem}[The trace splits $N$]\label{thm:split}
Let $a \le b$ be positive integers with $ab = N$ and $a+b = s$, and let $p \le q$. Then $a = p$
and $b = q$. Moreover $s^2 - 4N = (q-p)^2$ is a perfect square.
\end{theorem}

\begin{proof}[Proof sketch]
Eliminating $b$ and $d$ from $ab = cd$, $a+b = c+d$ yields $(a-c)(a-d) = 0$, and either factor
forces the ordered pairs to agree. The discriminant identity is $(p+q)^2 - 4pq = (q-p)^2$.
\end{proof}

\begin{corollary}[Completeness of the witness]
An exhaustive gcd scan of the $N$ residues yields $M_1(N)$, hence $s$, hence $(p,q)$ by solving
$t^2 - st + N = 0$. The witness is complete; its cost is $\Theta(N)$ gcd evaluations.
\end{corollary}

\section{Cost: variance and witness density}

\begin{theorem}[Elementary bounds]\label{thm:elem}
For $n \ge 1$, $n^k \le M_k(n)$, since $x=0$ alone contributes $n^k$. For a semiprime and
$k \ge 1$, $M_k(N) \le 4N^k$.
\end{theorem}

\begin{proof}[Proof sketch]
The lower bound is a single-term estimate. For the upper bound each of the four terms of
Theorem~\ref{thm:fourterm} is at most $N^k$: $(p-1)(q-1) \le N \le N^k$ and
$p^k(q-1) \le p^{k-1}pq \le (pq)^k$, similarly for $q$.
\end{proof}

\begin{definition}
For $U$ uniform on $\{0,\dots,N-1\}$ put
$V_k(N) = \Var\big(\gcd(N,U)^k\big) = M_{2k}(N)/N - \big(M_k(N)/N\big)^2$.
\end{definition}

\begin{theorem}[Variance is $\Theta(N^{2k-1})$]\label{thm:var}
For a semiprime $N$ and $k \ge 1$,
\[
  N^{2k-1} - 16N^{2k-2} \;\le\; V_k(N) \;\le\; 4N^{2k-1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
$M_{2k}(N) \ge N^{2k}$ gives $M_{2k}/N \ge N^{2k-1}$; $M_k \le 4N^k$ gives
$(M_k/N)^2 \le 16N^{2k-2}$. For the upper bound, $M_{2k} \le 4N^{2k}$ and the subtracted square
is nonnegative.
\end{proof}

The mechanism is transparent: $\gcd(N,U)^k$ equals $1$ with probability $1-(p+q-1)/N$, equals
$p^k$ or $q^k$ with probability about $1/q$ and $1/p$, and equals $N^k$ with probability exactly
$1/N$. The last event contributes $N^{2k-1}$ to the variance and dominates everything else.

\begin{theorem}[First moment is the cheap end]\label{thm:sep}
$V_1(N) \le 4N$, and for $N \ge 32$,
\[
  \frac{N^2}{8}\,V_1(N) \;\le\; V_2(N).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$V_1 \le M_2/N \le 4N$ by Theorem~\ref{thm:elem}; combine with $V_2 \ge N^3 - 16N^2$ from
Theorem~\ref{thm:var} and $N \ge 32$, which gives $N^3 - 16N^2 \ge N^3/2$.
\end{proof}

Through Chebyshev's inequality, estimating $\mathbb{E}[\gcd(N,U)^k]$ to a fixed absolute accuracy
requires $\bigOmega(V_k) = \bigOmega(N^{2k-1})$ samples: higher moments are strictly and
dramatically worse, and the exhaustive $\Theta(N)$ scan at $k=1$ is the optimal member of the
family. At $N = 943$ the ratio of Chebyshev sample counts between $k=2$ and $k=1$ is about
$8.5\times10^{5}$, and between $k=3$ and $k=1$ about $7.5\times10^{11}$.

\begin{theorem}[Witness density]\label{thm:density}
For a semiprime $N = pq$, $\#\{x < N : \gcd(N,x) \ne 1\} = p+q-1$.
\end{theorem}

\begin{proof}[Proof sketch]
The complementary set has $\varphi(N) = (p-1)(q-1)$ elements and $N-(p-1)(q-1) = p+q-1$.
\end{proof}

A uniform probe therefore meets a nontrivial gcd with probability exactly $(p+q-1)/N$: the
$\Theta(p+q)$ query threshold. For balanced $1024$-bit primes this is of order $2^{-1023}$.

\section{Primality, squarefreeness and the two-sided bracket}

\begin{definition}
The \emph{local factor} of $a \ge 1$ is $L_k(a) = a^k + a - 1$, so $M_k(p) = L_k(p)$ for prime
$p$. Put $\Pi_k(n) = \prod_{p^e\|n} L_k(p)^e$, the product over the primes of $n$ with
multiplicity.
\end{definition}

\begin{theorem}[Gauss-type lower bound; primality detection]\label{thm:gauss}
For $n \ge 2$ and $k \ge 1$, $M_k(n) \ge n^k+n-1$, with equality \emph{if and only if $n$ is
prime}.
\end{theorem}

\begin{proof}[Proof sketch]
The divisor form contains the terms $d=n$ and $d=1$, giving $M_k(n) \ge n^k + \varphi(n)$. For
prime $n$ this is an equality with $\varphi(n) = n-1$. For composite $n$ there is a further
divisor $1 < d < n$, whose weight $d^k\varphi(n/d) \ge d$ strictly exceeds the totient deficiency
$n-1-\varphi(n)$.
\end{proof}

\begin{theorem}[Prime-power strictness and exact deficiency]\label{thm:defic}
For $p$ prime, $k \ge 1$ and $e \ge 2$, $M_k(p^e) < L_k(p)^e$. At $e=2$,
\[
  L_k(p)^2 - M_k(p^2) \;=\; (p-1)(p^k-1),
\]
and in general, with $L = L_k(p)$,
\[
  L^e - M_k(p^e) \;=\; (p-1)\sum_{i=0}^{e-1} p^{ik}\big(L^{\,e-1-i} - p^{\,e-1-i}\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induct with $M_k(p^{e+1}) = p^kM_k(p^e) + \varphi(p^{e+1})$ against
$L^{e+1} = p^kL^e + L^e(p-1)$; the difference telescopes into the displayed sum. Every summand is
nonnegative and the $i=0$ term is positive for $e \ge 2$ since $L > p$.
\end{proof}

\begin{theorem}[The two-sided bracket]\label{thm:bracket}
For $n \ge 2$ and $k \ge 1$,
\[
  n^k+n-1 \;\le\; M_k(n) \;\le\; \Pi_k(n),
\]
with left equality exactly when $n$ is prime and right equality exactly when $n$ is squarefree.
The bracket collapses to a point precisely at the primes.
\end{theorem}

\begin{example}
At $k=2$: $M_2(4) = 22 < 25$, $M_2(8) = 92 < 125$, $M_2(9) = 105 < 121$, while
$M_2(6) = 55 = \Pi_2(6)$ and $M_2(15) = 319 = \Pi_2(15)$.
\end{example}

\section{The refinement lattice of a modulus}

\begin{definition}
For a list $\ell = (a_1,\dots,a_r)$ of integers $\ge 2$ put
$E_k(\ell) = \prod_{i=1}^{r}\big(a_i^k+a_i-1\big)$, the moment \emph{predicted} by the
factorisation $n = a_1\cdots a_r$. For $r=2$,
\[
  E_k(a,b) = (a^k+a-1)(b^k+b-1) = a^k(b-1) + b^k(a-1) + (a-1)(b-1) + (ab)^k,
\]
so $E_k(p,q) = M_k(pq)$ for a genuine prime pair by Theorem~\ref{thm:fourterm}.
\end{definition}

The factorisations of a fixed $n$ form a poset under refinement, with minimum the trivial
factorisation $[\,n\,]$ and maximum the prime factorisation.

\begin{lemma}[Refinement law]\label{lem:refine}
For $u,v \ge 2$ and $k \ge 1$, $(uv)^k + uv - 1 < (u^k+u-1)(v^k+v-1)$.
\end{lemma}

\begin{proof}[Proof sketch]
The difference of the two sides equals $(v-1)(u^k-1) + (u-1)(v^k-1)$, which is positive.
\end{proof}

\begin{theorem}[Unique minimiser]\label{thm:min}
For any factorisation $\ell$ of $n$ into parts $\ge 2$, $E_k(\ell) \ge n^k+n-1$, with equality if
and only if $\ell = [\,n\,]$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on the length, applying Lemma~\ref{lem:refine} with $u$ the first part and $v$ the product
of the remaining parts (which is $\ge 2$ when the tail is nonempty).
\end{proof}

\begin{theorem}[Unique maximiser]\label{thm:max}
For any factorisation $\ell$ of $n$ into parts $\ge 2$, $E_k(\ell) \le \Pi_k(n)$, with equality if
and only if every part of $\ell$ is prime.
\end{theorem}

\begin{proof}[Proof sketch]
$\Pi_k$ is completely multiplicative, so $\Pi_k(n) = \prod_i\Pi_k(a_i)$, and for each part
$L_k(a) \le \Pi_k(a)$ with equality iff $a$ is prime, by Lemma~\ref{lem:refine} applied to a
nontrivial splitting of a composite part. One strict local factor makes the product strict.
\end{proof}

\begin{corollary}[No collision involves an extremal factorisation]\label{cor:extremal}
If two factorisations of the same modulus have equal predicted moments and one of them is the
prime factorisation, then the other is a permutation of it; likewise if one of them is the trivial
factorisation.
\end{corollary}

\begin{lemma}\label{lem:length}
A factorisation of $n$ into parts $\ge 2$ has at most $\bigOmega(n)$ parts, with equality if and
only if every part is prime.
\end{lemma}

\section{Inversion: which moments determine the factorisation?}

\subsection{$k=2$: an exact collision law and a complete census}

\begin{theorem}[Collision law at $k=2$]\label{thm:collision2}
If $ab = cd$ then
\[
  E_2(a,b) = E_2(c,d) \iff \big(a+b = c+d\big)\ \text{ or }\ \big(a+b+c+d = ab-1\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
With $N = ab = cd$ and $\sigma = a+b$, $\tau = c+d$ one has
$E_2 = N^2+3N+1+(N-1)\sigma-\sigma^2$, so the difference of the two predictions factors as
$(\sigma-\tau)(N-1-\sigma-\tau)$.
\end{proof}

\begin{theorem}[Complete classification of two-part second-moment collisions]\label{thm:census2}
Suppose $2 \le a \le b$, $c \le d$, $a < c$, $ab = cd$ and $E_2(a,b) = E_2(c,d)$. Then
\[
  (a,b,c,d) = (2,14,4,7) \quad\text{or}\quad (a,b,c,d) = (2,18,3,12).
\]
Thus $N = 28$ and $N = 36$ are the only moduli in the whole number line carrying a genuine
second-moment collision between two-part factorisations.
\end{theorem}

\begin{proof}[Proof sketch]
Since $a < c$, equal sums are impossible (equal sum and product force equal pairs), so
$a+b+c+d+1 = N$ by Theorem~\ref{thm:collision2}. From $a \ge 2$ and $c \ge 3$ one gets
$2(a+b) \le 4+N$ and $3(c+d) \le 9+N$; adding these to the collision equation forces $N \le 36$,
then $a \le 6$ and $c \le 6$, and a finite check over the surviving quadruples leaves exactly the
two solutions.
\end{proof}

Both collisions involve a composite part on each side; in particular no distinct-prime semiprime
is affected.

\subsection{$k \ge 3$: strict monotonicity in the spread}

\begin{theorem}[Spread monotonicity, unconditional]\label{thm:spread}
Let $2 \le a < c \le d < b$ with $ab = cd$ and let $k \ge 3$. Then $E_k(c,d) < E_k(a,b)$: among
factorisations of a fixed modulus into two parts, the prediction increases strictly with the
spread.
\end{theorem}

\begin{proof}[Proof sketch]
Since $(ab)^k = (cd)^k$, only the tail $T_k(a,b) = a^k(b-1)+b^k(a-1)+(a-1)(b-1)$ matters, and
$b > d \ge c > a$ makes $b^k(a-1)$ dominant. Under the side condition $a+b+c+d < ab$ the
difference factors through a cubic bracket that is positive on $2 \le a < c \le d$. The side
condition holds automatically once $ab \ge 31$; below that an enumeration leaves exactly seven
exceptional quadruples,
\[
  (2,6;3,4),\ (2,8;4,4),\ (2,9;3,6),\ (2,10;4,5),\ (2,12;3,8),\ (2,12;4,6),\ (2,15;3,10),
\]
all of the shape $a=2$. For these, $T_k(2,b) = 2^k(b-1)+b^k+(b-1)$ and the base inequality
$T_3(c,d) < b^3$ propagates upward in $k$.
\end{proof}

\begin{corollary}[Identifiability at $k \ge 3$]\label{cor:ident3}
For $k \ge 3$, any two factorisations $ab = cd$ of the same modulus with $2 \le a \le b$,
$2 \le c \le d$ and $E_k(a,b) = E_k(c,d)$ satisfy $a=c$ and $b=d$.
\end{corollary}

\subsection{The capstone for semiprimes}

\begin{theorem}[Every moment factors a semiprime]\label{thm:capstone}
Let $N = pq$ with $p<q$ prime, let $k \ge 1$, and let $2 \le a \le b$ with $ab = N$ and
$E_k(a,b) = M_k(N)$. Then $a = p$ and $b = q$.
\end{theorem}

\begin{proof}[Proof sketch]
Three regimes. At $k=1$ matching predictions forces $a+b = p+q$ (the prediction is affine in the
trace) and Theorem~\ref{thm:split} concludes. At $k=2$ a mismatch would be a two-part
second-moment collision, hence $28$ or $36$ by Theorem~\ref{thm:census2}; both have a composite
part, contradicting that one side is the prime pair. At $k \ge 3$ apply
Corollary~\ref{cor:ident3}.
\end{proof}

Thus the feared ``root ambiguity'' at higher $k$ never materialises: the family carries complete
information at every order, and only the cost of obtaining the value distinguishes the orders.

\subsection{Beyond semiprimes: separation controlled by $\bigOmega$}

\begin{theorem}[No collision below three prime factors]\label{thm:omega2}
Let $k \ge 1$ and $n \ge 2$ with $\bigOmega(n) \le 2$. If two factorisations $\ell,m$ of $n$ into
parts $\ge 2$ satisfy $E_k(\ell) = E_k(m)$ then $\ell$ and $m$ agree up to order.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:length} both lists have length $\le 2$. If either has length $1$ it is the
trivial factorisation and Corollary~\ref{cor:extremal} applies; otherwise both have length $2$,
so all their parts are prime by Lemma~\ref{lem:length} again, and
Corollary~\ref{cor:extremal} applies at the other end.
\end{proof}

\begin{corollary}
For $n = pq$ a product of two primes and any $k \ge 1$, the predicted moment is injective on
factorisations up to order --- including at $k=2$, where it is not injective in general.
\end{corollary}

\begin{theorem}[Three prime factors]\label{thm:omega3}
Let $n \ge 2$ with $\bigOmega(n) \le 3$. If $k = 1$, or if $k \ge 3$, then equal predicted moments
imply equal factorisations up to order.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:omega2} leaves only two-part factorisations unconstrained at $\bigOmega(n)=3$;
on those $E_k$ is the pair prediction, so the required separation is
Corollary~\ref{cor:ident3} for $k \ge 3$ and the sum-and-product argument of
Theorem~\ref{thm:split} for $k=1$. Symmetry of $E_k$ upgrades sorted separation to separation up
to order.
\end{proof}

\begin{remark}[Sharpness]
At $k=2$ the modulus $28$ has $\bigOmega = 3$ and collides ($2\cdot14$ versus $4\cdot7$, both
predicting $1045$), so the hypothesis $k \ge 3$ in Theorem~\ref{thm:omega3} cannot be dropped; the
third moment separates the same pair. At $k=1$ the smallest collision is
$234 = 2\cdot9\cdot13 = 3\cdot3\cdot26$ with $\bigOmega(234) = 4$, so $\bigOmega \le 3$ cannot be
dropped either. An exhaustive census over $n \le 400$ finds no collision at all at $k=3,4$; at
$k=1$ only $234$, $288$, $400$, all with $\bigOmega \ge 4$; and at $k=2$ every collision is a
multiple of the two base collisions, always with $\bigOmega \ge 3$ and a composite part on both
sides.
\end{remark}

\section{Algorithms}

\paragraph{Algorithm A (trace-witness factoring; exact, $\Theta(N)$).}
Compute $M_1(N) = \sum_{x<N}\gcd(N,x)$ by an exhaustive scan; set $s = (4N+1-M_1)/2$; compute
$D = s^2-4N$ and $r = \sqrt D$; return $\big((s-r)/2,(s+r)/2\big)$. Correctness is
Corollary~\ref{cor:trace} with Theorem~\ref{thm:split}. Cost: $N$ gcd evaluations.

\paragraph{Algorithm B (moment evaluation from a known factorisation).}
Given $n = \prod p_i^{e_i}$, return $\prod_i M_k(p_i^{e_i})$ by
Proposition~\ref{prop:local}. This is the fast route, and it is \emph{circular} from an
adversary's viewpoint: it consumes the very factorisation the moment was to reveal.

\paragraph{Algorithm C (moment inversion / candidate scan).}
Given $n$, $k$ and an observed value $V$, enumerate divisors $a \le \sqrt n$ and return every pair
$(a,n/a)$ with $E_k(a,n/a) = V$. By Theorem~\ref{thm:capstone} the output is a single pair whenever
$n$ is a distinct-prime semiprime; by Theorem~\ref{thm:census2} the only exceptional moduli at
$k=2$ for two-part factorisations are $28$ and $36$.

\section{Discussion: four independent obstructions}

\begin{enumerate}
\item \textbf{Symmetry.} By Theorem~\ref{thm:closed}, $M_k = F_k(N,s)$: the hidden primes appear
only through their elementary symmetric functions, so the trace is a \emph{ceiling}. No member of
the family, and no combination of members, reveals anything about $(p,q)$ beyond $s$.
\item \textbf{Aggregation cost.} The value is a sum over all $N$ residues. Statistical shortcuts
are excluded quantitatively by Theorem~\ref{thm:var}: the variance $\Theta(N^{2k-1})$ is dominated
by the single residue $x=0$, and Theorem~\ref{thm:sep} makes the hierarchy strictly increasing in
cost. A uniform probe meets a nontrivial gcd with probability only $(p+q-1)/N$
(Theorem~\ref{thm:density}).
\item \textbf{Circularity.} The polynomial-time route to the value (Theorem~\ref{thm:divisor})
needs the factorisation of $n$; the closed form needs $s$; the only factorisation-free route is
enumeration.
\item \textbf{Known method.} $M_1(n) = \sum_{d\mid n}d\,\varphi(n/d)$ is the classical gcd-sum
function and the whole family is the convolution $\Id_k * \varphi$: nothing in the family is new
as an object. What is new is the exact accounting of what it can and cannot deliver.
\end{enumerate}

The positive content is the structure theory: the bracket with its two exact equality
characterisations, the exact prime-power deficiency, the strict refinement law, the uniqueness of
both extremes of the refinement order, the complete census of second-moment collisions, and the
unconditional identifiability at every $k \ge 3$.

\section{Future directions}

\begin{itemize}
\item \emph{The general $r$-factor conjecture.} Is it true that for $k \ge 3$ the predicted moment
separates all factorisations of \emph{every} modulus? No counterexample exists up to $400$. The
obstruction is that pair separation handles only two-part factorisations while extremal uniqueness
constrains only the ends of the lattice; the interior at $\bigOmega(n) \ge 4$ needs a new
inequality.
\item \emph{The $k=1$ collision structure.} Is there a classification of first-moment collisions
analogous to Theorem~\ref{thm:census2}, perhaps a parametric family generating all of them from
$234 = 2\cdot9\cdot13 = 3\cdot3\cdot26$?
\item \emph{Sharp variance constants.} Theorem~\ref{thm:var} pins $V_k$ to
$[N^{2k-1}-16N^{2k-2},\,4N^{2k-1}]$; an asymptotic $V_k \sim N^{2k-1}$ with explicit error would
sharpen the sampling lower bound.
\item \emph{Deficiency at general moduli.} A closed form for $\Pi_k(n)-M_k(n)$ at an arbitrary
modulus would quantify the squarefreeness characterisation of Theorem~\ref{thm:bracket}.
\item \emph{Other symmetric aggregates.} Which other elementary aggregates of a semiprime have the
trace as their ceiling, and is there a natural class of statistics for which this can be proved?
\end{itemize}

\section{Conclusion}

The gcd moments of a semiprime form a closed family: each is an explicit polynomial in the public
modulus and the trace $s = p+q$; the first moment determines the trace; the trace determines the
factorisation; and every higher moment is a function of the modulus and the first moment.
Inversion is unambiguous at every order, and the residual ambiguity of the general problem is
completely mapped. What the family does not do is factor efficiently, and the reasons are exact
rather than heuristic: symmetry caps the information at the trace, the variance $\Theta(N^{2k-1})$
caps sampling, the fast evaluation route is circular, and the object itself is classical. The gcd
moment is a secret written down in full, and still perfectly safe --- because the only way to read
it is to do the work one was trying to avoid.

\end{document}

