"""Certification sweep: every identity of the theory, checked over a large range.

This is a single-purpose stress test.  It verifies, by exhaustive computation:

  1. the divisor form            M_k(n) = sum_{d|n} d^k phi(n/d)   for all n <= 300, k <= 4;
  2. multiplicativity            M_k(mn) = M_k(m) M_k(n) for coprime m, n;
  3. the semiprime closed form   M_k(pq) = N^k + N P_{k-1} - P_k + N - s + 1;
  4. the four explicit low-order polynomials in (N, s);
  5. the Euler product           M_k(n) = prod_{p|n} (p^k + p - 1) for squarefree n;
  6. the primality characterisation  M_k(n) = n^k + n - 1  <=>  n prime;
  7. the squarefree characterisation M_k(n) = Pi_k(n)      <=>  n squarefree;
  8. the exact prime-power deficiency formula;
  9. the refinement law and the uniqueness of both lattice extremes;
 10. the exact witness density  #{x < N : gcd(N,x) != 1} = p + q - 1.

Every check is an assertion; the script prints a tally and exits silently on success.
"""

from __future__ import annotations

import math
from typing import Iterable, List, Tuple


def divisors(n: int) -> List[int]:
    small, large = [], []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def totient(n: int) -> int:
    result, m, d = n, n, 2
    while d * d <= m:
        if m % d == 0:
            while m % d == 0:
                m //= d
            result -= result // d
        d += 1
    if m > 1:
        result -= result // m
    return result


def prime_factor_list(n: int) -> List[int]:
    out, m, d = [], n, 2
    while d * d <= m:
        while m % d == 0:
            out.append(d)
            m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def is_prime(n: int) -> bool:
    return n >= 2 and len(prime_factor_list(n)) == 1


def is_squarefree(n: int) -> bool:
    f = prime_factor_list(n)
    return len(set(f)) == len(f)


def moment_scan(k: int, n: int) -> int:
    return sum(math.gcd(n, x) ** k for x in range(n))


def moment_divisors(k: int, n: int) -> int:
    return sum(d**k * totient(n // d) for d in divisors(n))


def newton(big_n: int, s: int, j: int) -> int:
    a, b = 2, s
    if j == 0:
        return a
    for _ in range(j - 1):
        a, b = b, s * b - big_n * a
    return b


def closed_form(k: int, big_n: int, s: int) -> int:
    return big_n**k + big_n * newton(big_n, s, k - 1) - newton(big_n, s, k) + big_n - s + 1


def local(k: int, a: int) -> int:
    return a**k + a - 1


def prime_prod(k: int, n: int) -> int:
    out = 1
    for p in prime_factor_list(n):
        out *= local(k, p)
    return out


def predicted(k: int, parts: Iterable[int]) -> int:
    out = 1
    for a in parts:
        out *= local(k, a)
    return out


def factorisations(n: int, minimum: int = 2) -> List[List[int]]:
    if n == 1:
        return [[]]
    out: List[List[int]] = []
    for d in divisors(n):
        if d < minimum or d == 1:
            continue
        for tail in factorisations(n // d, d):
            out.append([d] + tail)
    return out


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(limit**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def main() -> None:
    checks = 0
    ks = (1, 2, 3, 4)

    # 1. divisor form
    for n in range(1, 301):
        for k in ks:
            assert moment_scan(k, n) == moment_divisors(k, n)
            checks += 1

    # 2. multiplicativity
    for m in range(1, 60):
        for n in range(1, 60):
            if math.gcd(m, n) == 1:
                for k in ks:
                    assert moment_divisors(k, m * n) == moment_divisors(k, m) * moment_divisors(k, n)
                    checks += 1

    # 3-4. semiprime closed form and the explicit polynomials
    primes = primes_up_to(60)
    for i, p in enumerate(primes):
        for q in primes[i + 1:]:
            big_n, s = p * q, p + q
            for k in ks:
                assert moment_divisors(k, big_n) == closed_form(k, big_n, s)
                checks += 1
            assert moment_divisors(1, big_n) == 4 * big_n - 2 * s + 1
            assert moment_divisors(2, big_n) == big_n**2 + 3 * big_n + 1 + (big_n - 1) * s - s**2
            assert moment_divisors(3, big_n) == (
                big_n**3 - 2 * big_n**2 + big_n * s**2 + 3 * big_n * s + big_n - s**3 - s + 1
            )
            assert moment_divisors(4, big_n) == (
                big_n**4 - 3 * big_n**2 * s - 2 * big_n**2 + big_n * s**3
                + 4 * big_n * s**2 + big_n - s**4 - s + 1
            )
            checks += 4
            # 10. witness density
            assert sum(1 for x in range(big_n) if math.gcd(big_n, x) != 1) == p + q - 1
            checks += 1
            # trace recovery inverts exactly
            assert (4 * big_n + 1 - moment_divisors(1, big_n)) // 2 == s
            checks += 1

    # 5-7. Euler product, bracket, and the two equality characterisations
    for n in range(2, 401):
        for k in ks:
            m = moment_divisors(k, n)
            assert local(k, n) <= m <= prime_prod(k, n)
            assert (m == local(k, n)) == is_prime(n)
            assert (m == prime_prod(k, n)) == is_squarefree(n)
            if is_squarefree(n):
                assert m == predicted(k, sorted(set(prime_factor_list(n))))
            checks += 4

    # 8. exact prime-power deficiency
    for p in primes_up_to(30):
        for k in ks:
            assert local(k, p) ** 2 - moment_divisors(k, p * p) == (p - 1) * (p**k - 1)
            checks += 1
            for e in range(0, 5):
                lhs = local(k, p) ** e - moment_divisors(k, p**e)
                rhs = (p - 1) * sum(
                    p ** (i * k) * (local(k, p) ** (e - 1 - i) - p ** (e - 1 - i))
                    for i in range(e)
                )
                assert lhs == rhs
                checks += 1

    # 9. refinement law and uniqueness of the extremes
    for u in range(2, 25):
        for v in range(2, 25):
            for k in ks:
                assert local(k, u * v) < local(k, u) * local(k, v)
                checks += 1
    for n in range(2, 200):
        for k in ks:
            rows = sorted((predicted(k, f), f) for f in factorisations(n))
            assert rows[0][1] == [n]
            assert sorted(rows[-1][1]) == sorted(prime_factor_list(n))
            if len(rows) > 1:
                assert rows[0][0] < rows[1][0]
                assert rows[-2][0] < rows[-1][0]
            checks += 1

    print(f"all {checks} certification checks passed")


if __name__ == "__main__":
    main()

