"""Algorithm D: enumerating the refinement lattice and locating its extremes.

Every factorisation n = a_1 * ... * a_r into parts >= 2 predicts the moment
E_k = prod_i (a_i^k + a_i - 1).  Splitting a part strictly increases E_k, so E_k
is strictly monotone for the refinement order.  Consequently the trivial
factorisation [n] is the unique minimiser (value n^k + n - 1) and the prime
factorisation is the unique maximiser (value Pi_k(n)), and the true moment M_k(n)
sits inside the resulting bracket, touching the left end exactly at primes and the
right end exactly at squarefree moduli.
"""

from __future__ import annotations

from typing import Dict, List, Tuple


def divisors(n: int) -> List[int]:
    small, large = [], []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def totient(n: int) -> int:
    result, m, d = n, n, 2
    while d * d <= m:
        if m % d == 0:
            while m % d == 0:
                m //= d
            result -= result // d
        d += 1
    if m > 1:
        result -= result // m
    return result


def prime_factor_list(n: int) -> List[int]:
    out, m, d = [], n, 2
    while d * d <= m:
        while m % d == 0:
            out.append(d)
            m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def gcd_moment(k: int, n: int) -> int:
    """M_k(n) = sum_{d | n} d^k phi(n/d)."""
    return sum(d**k * totient(n // d) for d in divisors(n))


def predicted_moment(k: int, parts: List[int]) -> int:
    out = 1
    for a in parts:
        out *= a**k + a - 1
    return out


def all_factorisations(n: int, minimum: int = 2) -> List[List[int]]:
    """Every unordered factorisation of n into parts >= 2, each ascending."""
    if n == 1:
        return [[]]
    out: List[List[int]] = []
    for d in divisors(n):
        if d < minimum or d == 1:
            continue
        for tail in all_factorisations(n // d, d):
            out.append([d] + tail)
    return out


def lattice_report(n: int, k: int) -> Dict[str, object]:
    """Enumerate the lattice, sort by prediction, and locate the bracket."""
    rows: List[Tuple[int, List[int]]] = sorted(
        (predicted_moment(k, f), f) for f in all_factorisations(n)
    )
    collisions = [
        (v1, f1, f2)
        for (v1, f1), (v2, f2) in zip(rows, rows[1:])
        if v1 == v2
    ]
    return {
        "modulus": n,
        "exponent": k,
        "true_moment": gcd_moment(k, n),
        "minimum": rows[0],
        "maximum": rows[-1],
        "table": rows,
        "collisions": collisions,
    }


if __name__ == "__main__":
    for n in (28, 36, 60):
        rep = lattice_report(n, 2)
        print(f"\nn = {n}, k = 2, M_2(n) = {rep['true_moment']}")
        for value, parts in rep["table"]:  # type: ignore[union-attr]
            print(f"   {str(parts):>18}  ->  {value}")
        print("   collisions:", rep["collisions"])

