"""Visualization: the refinement lattice of a modulus and its moment bracket.

For a chosen modulus n and exponent k, every factorisation of n into parts >= 2 is
drawn as a node, placed horizontally by its number of parts and vertically by the
moment it predicts, E_k = prod_i (a_i^k + a_i - 1).  Edges join a factorisation to
each of its one-step refinements (split one part into two).  Because splitting a
part strictly raises E_k, every edge points strictly upward: the picture is a
Hasse-style diagram of a strictly monotone function.

The trivial factorisation sits alone at the bottom (value n^k + n - 1) and the
prime factorisation alone at the top (value Pi_k(n)); the true moment M_k(n) is
drawn as a horizontal line inside the bracket, touching the top line exactly when n
is squarefree.  Colliding nodes -- factorisations with equal predictions, such as
2*14 and 4*7 at n = 28, k = 2 -- are highlighted in red.
"""

from __future__ import annotations

from collections import defaultdict
from typing import Dict, List, Tuple

import matplotlib.pyplot as plt


def divisors(n: int) -> List[int]:
    small, large = [], []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def totient(n: int) -> int:
    result, m, d = n, n, 2
    while d * d <= m:
        if m % d == 0:
            while m % d == 0:
                m //= d
            result -= result // d
        d += 1
    if m > 1:
        result -= result // m
    return result


def gcd_moment(k: int, n: int) -> int:
    return sum(d**k * totient(n // d) for d in divisors(n))


def predicted(k: int, parts: Tuple[int, ...]) -> int:
    out = 1
    for a in parts:
        out *= a**k + a - 1
    return out


def all_factorisations(n: int, minimum: int = 2) -> List[Tuple[int, ...]]:
    if n == 1:
        return [()]
    out: List[Tuple[int, ...]] = []
    for d in divisors(n):
        if d < minimum or d == 1:
            continue
        for tail in all_factorisations(n // d, d):
            out.append((d,) + tail)
    return out


def one_step_refinements(parts: Tuple[int, ...]) -> List[Tuple[int, ...]]:
    """All factorisations obtained by splitting exactly one part into two."""
    out = set()
    for i, a in enumerate(parts):
        for d in divisors(a):
            if 2 <= d <= a // d and a // d >= 2:
                new = list(parts[:i]) + [d, a // d] + list(parts[i + 1:])
                out.add(tuple(sorted(new)))
    return sorted(out)


def draw(n: int = 36, k: int = 2, filename: str = "gcd_moment_lattice.png") -> None:
    facs = all_factorisations(n)
    values = {f: predicted(k, f) for f in facs}
    by_length: Dict[int, List[Tuple[int, ...]]] = defaultdict(list)
    for f in facs:
        by_length[len(f)].append(f)

    pos: Dict[Tuple[int, ...], Tuple[float, float]] = {}
    for length, group in by_length.items():
        group.sort(key=lambda f: values[f])
        for j, f in enumerate(group):
            jitter = (j - (len(group) - 1) / 2) * 0.26
            pos[f] = (length + jitter, values[f])

    duplicates = defaultdict(list)
    for f, v in values.items():
        duplicates[v].append(f)
    colliding = {f for v, fs in duplicates.items() if len(fs) > 1 for f in fs}

    fig, ax = plt.subplots(figsize=(9.5, 7))
    for f in facs:
        for g in one_step_refinements(f):
            if g in pos:
                x0, y0 = pos[f]
                x1, y1 = pos[g]
                ax.annotate(
                    "",
                    xy=(x1, y1),
                    xytext=(x0, y0),
                    arrowprops=dict(arrowstyle="->", color="#bbbbbb", lw=0.9),
                )
    for idx, (f, (x, y)) in enumerate(sorted(pos.items(), key=lambda kv: kv[1])):
        colour = "#d62728" if f in colliding else "#1f77b4"
        ax.plot([x], [y], "o", color=colour, ms=8, zorder=3)
        ax.annotate(
            "$" + r" \cdot ".join(str(a) for a in f) + "$",
            (x, y),
            textcoords="offset points",
            xytext=(10, 6 if idx % 2 == 0 else -12),
            fontsize=9,
            color=colour,
        )

    true_moment = gcd_moment(k, n)
    ax.axhline(true_moment, color="#2ca02c", ls="--", lw=1.4,
               label=f"true moment $M_{{{k}}}({n}) = {true_moment}$")
    ax.axhline(n**k + n - 1, color="#777777", ls=":", lw=1.2,
               label=f"lower end $n^k+n-1 = {n ** k + n - 1}$")
    ax.axhline(max(values.values()), color="#777777", ls="-.", lw=1.2,
               label=f"upper end $\\Pi_{{{k}}}(n) = {max(values.values())}$")

    ax.set_xlabel("number of parts in the factorisation")
    ax.set_ylabel(f"predicted moment $E_{{{k}}}$")
    ax.set_title(
        f"Refinement lattice of $n = {n}$ at $k = {k}$:\n"
        "every split strictly raises the prediction; red nodes collide"
    )
    ax.legend(loc="upper left", fontsize=9)
    ax.grid(True, alpha=0.2)
    fig.tight_layout()
    fig.savefig(filename, dpi=160)
    print(f"wrote {filename}")


if __name__ == "__main__":
    draw(36, 2, "gcd_moment_lattice_36_k2.png")
    draw(28, 2, "gcd_moment_lattice_28_k2.png")
    draw(28, 3, "gcd_moment_lattice_28_k3.png")
